import { expect } from 'chai';
import { before, describe, it, after } from 'mocha';

import { getCredentials, api, request, credentials } from '../../data/api-data';
import { restorePermissionToRoles } from '../../data/permissions.helper';
import { IS_EE } from '../../e2e/config/constants';

(IS_EE ? describe : describe.skip)('[Guest Permissions]', () => {
	const guestPermissions = ['view-d-room', 'view-joined-room', 'view-p-room', 'start-discussion', 'mobile-upload-file'];

	before((done) => getCredentials(done));

	after(() => Promise.all(guestPermissions.map((permissionName) => restorePermissionToRoles(permissionName))));

	function succeedRemoveGuestPermission(permissionName: string) {
		it(`should allow removing the whitelisted permission ${permissionName} from the guest role`, async () => {
			await request
				.post(api('permissions.removeRole'))
				.set(credentials)
				.send({ permissionId: permissionName, role: 'guest' })
				.expect('Content-Type', 'application/json')
				.expect(200)
				.expect((res) => {
					expect(res.body).to.have.property('success', true);
				});

			const permissionsListRes = await request
				.get(api('permissions.listAll'))
				.set(credentials)
				.expect('Content-Type', 'application/json')
				.expect(200);
			expect(permissionsListRes.body).to.have.property('success', true);
			expect(permissionsListRes.body).to.have.property('update').and.to.be.an('array');
			expect(permissionsListRes.body).to.have.property('remove').and.to.be.an('array');

			const updatedPermission = permissionsListRes.body.update.find((permission: any) => permission._id === permissionName);
			expect(updatedPermission).to.have.property('_id', permissionName);
			expect(updatedPermission).to.have.property('roles').and.to.be.an('array').that.does.not.include('guest');
		});
	}

	function succeedAddGuestPermission(permissionName: string) {
		it(`should allow granting the whitelisted permission ${permissionName} to the guest role`, async () => {
			await request
				.post(api('permissions.addRole'))
				.set(credentials)
				.send({ permissionId: permissionName, role: 'guest' })
				.expect('Content-Type', 'application/json')
				.expect(200)
				.expect((res) => {
					expect(res.body).to.have.property('success', true);
				});

			const permissionsListRes = await request
				.get(api('permissions.listAll'))
				.set(credentials)
				.expect('Content-Type', 'application/json')
				.expect(200);
			expect(permissionsListRes.body).to.have.property('success', true);
			expect(permissionsListRes.body).to.have.property('update').and.to.be.an('array');
			expect(permissionsListRes.body).to.have.property('remove').and.to.be.an('array');

			const updatedPermission = permissionsListRes.body.update.find((permission: any) => permission._id === permissionName);
			expect(updatedPermission).to.have.property('_id', permissionName);
			expect(updatedPermission).to.have.property('roles').and.to.be.an('array').that.includes('guest');
		});
	}

	describe('Default guest roles', () => {
		guestPermissions.forEach((permissionName) => {
			succeedRemoveGuestPermission(permissionName);
		});

		guestPermissions.forEach((permissionName) => {
			succeedAddGuestPermission(permissionName);
		});

		it('should not allow adding a non whitelisted permission to the guest role', async () => {
			await request
				.post(api('permissions.addRole'))
				.set(credentials)
				.send({ permissionId: 'create-c', role: 'guest' })
				.expect('Content-Type', 'application/json')
				.expect(400)
				.expect((res) => {
					expect(res.body).to.have.property('success', false);
					expect(res.body).to.have.property('error').that.includes('Permission is restricted');
					expect(res.body).to.have.property('errorType', 'error-action-not-allowed');
				});
		});
	});
});

import { expect } from 'chai';
import { after, before, describe, it } from 'mocha';
import type { Response } from 'supertest';

import { getCredentials, api, request, credentials } from '../../data/api-data';
import { password } from '../../data/user';
import { createUser, deleteUser, login } from '../../data/users.helper';

async function authorizeAndExchange(loginToken: string, cId: string, cSecret: string, redirectUri: string) {
	const authRes = await request
		.post(`/oauth/authorize`)
		.type('form')
		.send({
			token: loginToken,
			client_id: cId,
			response_type: 'code',
			redirect_uri: redirectUri,
			state: 'test-state',
			allow: 'yes',
		})
		.expect(302);

	const location = new URL(authRes.headers.location);
	const code = location.searchParams.get('code') as string;

	const tokenRes = await request
		.post(`/oauth/token`)
		.type('form')
		.send({
			grant_type: 'authorization_code',
			code,
			client_id: cId,
			client_secret: cSecret,
			redirect_uri: redirectUri,
		})
		.expect(200);

	return { accessToken: tokenRes.body.access_token as string, refreshToken: tokenRes.body.refresh_token as string };
}

describe('[OAuth Server]', () => {
	let oAuthAppId: string;
	let clientId: string;
	let clientSecret: string;
	let code: string;
	let refreshToken: string;
	let accessToken: string;
	let refreshedAccessToken: string;
	const redirectUri = 'http://asd.com';

	before((done) => getCredentials(done));

	after(async () => {
		await request
			.post(api('oauth-apps.delete'))
			.set(credentials)
			.send({ appId: oAuthAppId })
			.expect('Content-Type', 'application/json')
			.expect(200);
	});

	describe('[/oauth-apps.create]', () => {
		it('should create the oauth app', async () => {
			const data = {
				name: 'api-test',
				redirectUri: 'http://test.com,http://asd.com',
				active: true,
			};

			await request
				.post(api('oauth-apps.create'))
				.set(credentials)
				.send(data)
				.expect('Content-Type', 'application/json')
				.expect(200)
				.expect((res: Response) => {
					expect(res.body).to.have.property('success', true);
					expect(res.body).to.have.property('application');
					expect(res.body.application).to.have.property('_id');
					expect(res.body.application).to.have.property('name', data.name);
					expect(res.body.application).to.have.property('redirectUri', data.redirectUri);
					expect(res.body.application).to.have.property('active', data.active);
					expect(res.body.application).to.have.property('clientId');
					expect(res.body.application).to.have.property('clientSecret');
					oAuthAppId = res.body.application._id;
					clientId = res.body.application.clientId;
					clientSecret = res.body.application.clientSecret;
				});
		});

		it('should authorize oauth to retrieve code', async () => {
			const params = new URLSearchParams({
				scope: 'user',
				response_type: 'token,code',
				response_mode: 'form_post',
				state: 'xus2t6ix57g',
			});

			await request
				.post(`/oauth/authorize?${params.toString()}`)
				.type('form')
				.send({
					token: credentials['X-Auth-Token'],
					client_id: clientId,
					response_type: 'code',
					redirect_uri: redirectUri,
					allow: 'yes',
				})
				.expect(302)
				.expect((res: Response) => {
					expect(res.headers).to.have.property('location');
