		expect(await canBypassRateLimit('legacyBot')).to.be.false;
	});
});

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
/**
 * Retry a given function N times until it succeeds.
 * It should not be as workaround for eventual consistency, but in cases api calls have to be retried because of async tasks, it must be intentionally used.
 *
 * @param {Function} fn - Function that performs the assert/check.
 * @param {number} retries - Number of retries.
 * @param {number} delayMs - Delay between retries (ms).
 */
export async function retry(_description: string, fn: () => Promise<void> | void, options: { retries?: number; delayMs?: number } = {}) {
	const { retries = 3, delayMs = 10 } = options;
	let lastError;

	await delay(delayMs);
	for (let i = 0; i <= retries; i++) {
		try {
			const result = fn();
			if (result instanceof Promise) {
				await result;
			}
			return;
		} catch (err) {
			lastError = err;
			if (i < retries && delayMs > 0) {
				await delay(delayMs);
			}
		}
	}

	throw lastError;
}

import { expect } from 'chai';

import { replaceVariables } from '../../../../../../server/lib/notifications/email/replaceVariables';

describe('Mailer-API', () => {
	describe('replaceVariables', () => {
		const i18n: {
			[key: string]: string;
		} = {
			key: 'value',
		};

		describe('single key', function functionName() {
			it(`should be equal to test ${i18n.key}`, () => {
				expect(`test ${i18n.key}`).to.be.equal(replaceVariables('test {key}', (_match, key) => i18n[key]));
			});
		});

		describe('multiple keys', function functionName() {
			it(`should be equal to test ${i18n.key} and ${i18n.key}`, () => {
				expect(`test ${i18n.key} and ${i18n.key}`).to.be.equal(replaceVariables('test {key} and {key}', (_match, key) => i18n[key]));
			});
		});

		describe('key with a trailing space', function functionName() {
			it(`should be equal to test ${i18n.key}`, () => {
				expect(`test ${i18n.key}`).to.be.equal(replaceVariables('test {key }', (_match, key) => i18n[key]));
			});
		});

		describe('key with a leading space', function functionName() {
			it(`should be equal to test ${i18n.key}`, () => {
				expect(`test ${i18n.key}`).to.be.equal(replaceVariables('test { key}', (_match, key) => i18n[key]));
			});
		});

		describe('key with leading and trailing spaces', function functionName() {
			it(`should be equal to test ${i18n.key}`, () => {
				expect(`test ${i18n.key}`).to.be.equal(replaceVariables('test { key }', (_match, key) => i18n[key]));
			});
		});

		describe('key with multiple words', function functionName() {
			it(`should be equal to test ${i18n.key}`, () => {
				expect(`test ${i18n.key}`).to.be.equal(replaceVariables('test {key ignore}', (_match, key) => i18n[key]));
			});
		});

		describe('key with multiple opening brackets', function functionName() {
			it(`should be equal to test {${i18n.key}`, () => {
				expect(`test {${i18n.key}`).to.be.equal(replaceVariables('test {{key}', (_match, key) => i18n[key]));
			});
		});

		describe('key with multiple closing brackets', function functionName() {
			it(`should be equal to test ${i18n.key}}`, () => {
				expect(`test ${i18n.key}}`).to.be.equal(replaceVariables('test {key}}', (_match, key) => i18n[key]));
			});
		});

		describe('key with multiple opening and closing brackets', function functionName() {
			it(`should be equal to test {${i18n.key}}`, () => {
				expect(`test {${i18n.key}}`).to.be.equal(replaceVariables('test {{key}}', (_match, key) => i18n[key]));
			});
		});
	});
});

import { isOmnichannelRoom } from '@rocket.chat/core-typings';
import type { ISubscription, IMessage, IRoom } from '@rocket.chat/core-typings';
import { useRouter, useUser } from '@rocket.chat/ui-contexts';

import type { MessageActionConfig } from '../../../lib/MessageAction';
import { useMarkAsUnreadMutation } from '../hooks/useMarkAsUnreadMutation';

export const useMarkAsUnreadMessageAction = (
	message: IMessage,
	{ room, subscription }: { room: IRoom; subscription: ISubscription | undefined },
): MessageActionConfig | null => {
	const user = useUser();
	const { mutateAsync: markAsUnread } = useMarkAsUnreadMutation();

	const router = useRouter();

	if (isOmnichannelRoom(room) || !user) {
		return null;
	}

	if (!subscription) {
		return null;
	}

	if (message.u._id === user._id) {
		return null;
	}

	return {
		id: 'mark-message-as-unread',
		icon: 'flag',
		label: 'Mark_unread',
		context: ['message', 'message-mobile', 'threads', 'federated'],
		type: 'interaction',
		async action() {
			router.navigate('/home');
			await markAsUnread({ message, subscription });
		},
		order: 4,
		group: 'menu',
	};
};

import {
	type IMessage,
	type ISubscription,
	type IRoom,
	isOmnichannelRoom,
	isRoomFederated,
	isRoomNativeFederated,
} from '@rocket.chat/core-typings';
import { useRouter, useSetting } from '@rocket.chat/ui-contexts';
import { useTranslation } from 'react-i18next';

import MessageToolbarItem from '../../MessageToolbarItem';

export type ReplyInThreadMessageActionProps = {
	message: IMessage;
	room: IRoom;
	subscription: ISubscription | undefined;
};

const ReplyInThreadMessageAction = ({ message, room, subscription }: ReplyInThreadMessageActionProps) => {
	const router = useRouter();
	const threadsEnabled = useSetting('Threads_enabled', true);
	const { t } = useTranslation();

	if (!threadsEnabled || isOmnichannelRoom(room) || !subscription) {
		return null;
	}
	const isFederated = room && isRoomFederated(room);
	const isFederationBlocked = isFederated && !isRoomNativeFederated(room);

	if (isFederationBlocked) {
		return null;
	}

	return (
		<MessageToolbarItem
			id='reply-in-thread'
			icon='thread'
			title={t('Reply_in_thread')}
			onClick={(event) => {
				event.stopPropagation();
				const routeName = router.getRouteName();

				if (routeName) {
					router.navigate({
						name: routeName,
						params: {
							...router.getRouteParameters(),
							tab: 'thread',
							context: message.tmid || message._id,
						},
					});
				}
			}}
		/>
	);
};

export default ReplyInThreadMessageAction;
